    course text,
    score integer,
    par integer DEFAULT 72,
    holes integer DEFAULT 18,
    putts integer,
    fairways_hit integer,
    greens_in_regulation integer,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: golf_sessions; Type: TABLE; Schema: public; Owner: -
