20260618162821	{"-- Spendee Clone schema\ncreate table if not exists public.wallets (\n  id               uuid primary key default gen_random_uuid(),\n  user_id          uuid not null references auth.users (id) on delete cascade,\n  name             text not null,\n  currency         text not null default 'USD',\n  starting_balance numeric(14,2) not null default 0,\n  color            text not null default '#19c2a8',\n  created_at       timestamptz not null default now()\n);\n\ncreate table if not exists public.categories (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references auth.users (id) on delete cascade,\n  name       text not null,\n  type       text not null check (type in ('income','expense')),\n  color      text not null default '#8aa0bd',\n  icon       text not null default 'tag',\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists public.transactions (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references auth.users (id) on delete cascade,\n  wallet_id   uuid not null references public.wallets (id) on delete cascade,\n  category_id uuid references public.categories (id) on delete set null,\n  type        text not null check (type in ('income','expense')),\n  amount      numeric(14,2) not null check (amount >= 0),\n  note        text,\n  occurred_on date not null default current_date,\n  created_at  timestamptz not null default now()\n);\n\ncreate index if not exists transactions_user_date_idx\n  on public.transactions (user_id, occurred_on desc);\n\ncreate table if not exists public.budgets (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references auth.users (id) on delete cascade,\n  category_id uuid not null references public.categories (id) on delete cascade,\n  amount      numeric(14,2) not null check (amount > 0),\n  created_at  timestamptz not null default now(),\n  unique (user_id, category_id)\n);\n\nalter table public.wallets      enable row level security;\nalter table public.categories   enable row level security;\nalter table public.transactions enable row level security;\nalter table public.budgets      enable row level security;\n\ndo $$\ndeclare\n  t text;\nbegin\n  foreach t in array array['wallets','categories','transactions','budgets']\n  loop\n    execute format('drop policy if exists \\"owner_select\\" on public.%I', t);\n    execute format('drop policy if exists \\"owner_insert\\" on public.%I', t);\n    execute format('drop policy if exists \\"owner_update\\" on public.%I', t);\n    execute format('drop policy if exists \\"owner_delete\\" on public.%I', t);\n    execute format('create policy \\"owner_select\\" on public.%I for select using (auth.uid() = user_id)', t);\n    execute format('create policy \\"owner_insert\\" on public.%I for insert with check (auth.uid() = user_id)', t);\n    execute format('create policy \\"owner_update\\" on public.%I for update using (auth.uid() = user_id) with check (auth.uid() = user_id)', t);\n    execute format('create policy \\"owner_delete\\" on public.%I for delete using (auth.uid() = user_id)', t);\n  end loop;\nend $$;\n\ncreate or replace function public.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  insert into public.wallets (user_id, name, currency, starting_balance)\n  values (new.id, 'Cash', 'USD', 0);\n  insert into public.categories (user_id, name, type, color, icon) values\n    (new.id, 'Salary',        'income',  '#28c76f', 'wallet'),\n    (new.id, 'Other income',  'income',  '#3fe0c6', 'plus'),\n    (new.id, 'Groceries',     'expense', '#19c2a8', 'cart'),\n    (new.id, 'Dining',        'expense', '#ffb648', 'food'),\n    (new.id, 'Transport',     'expense', '#5b8def', 'car'),\n    (new.id, 'Housing',       'expense', '#a78bfa', 'home'),\n    (new.id, 'Utilities',     'expense', '#22d3ee', 'bolt'),\n    (new.id, 'Health',        'expense', '#ff6b6b', 'heart'),\n    (new.id, 'Shopping',      'expense', '#f472b6', 'bag'),\n    (new.id, 'Entertainment', 'expense', '#facc15', 'play'),\n    (new.id, 'Other',         'expense', '#8aa0bd', 'tag');\n  return new;\nend $$;\n\ndrop trigger if exists on_auth_user_created on auth.users;\ncreate trigger on_auth_user_created\n  after insert on auth.users\n  for each row execute function public.handle_new_user();"}	spendee_initial_schema	tre.thitipat@gmail.com	\N	\N
20260618163002	{"revoke execute on function public.handle_new_user() from public, anon, authenticated;"}	harden_handle_new_user_revoke_execute	tre.thitipat@gmail.com	\N	\N
20260618164058	{"-- Remove the budgets feature entirely\ndrop table if exists public.budgets cascade;\n\n-- Reseed default categories for new users (Spendee-style, icon-based)\ncreate or replace function public.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  insert into public.wallets (user_id, name, currency, starting_balance)\n  values (new.id, 'Cash', 'USD', 0);\n\n  insert into public.categories (user_id, name, type, color, icon) values\n    (new.id, 'Salary',       'income',  '#34c759', 'wallet'),\n    (new.id, 'Other income', 'income',  '#30d158', 'plus'),\n    (new.id, 'Food',         'expense', '#ff9f0a', 'food'),\n    (new.id, 'Expenses',     'expense', '#8e8e93', 'expenses'),\n    (new.id, 'Shopping',     'expense', '#ff375f', 'shopping'),\n    (new.id, 'Transport',    'expense', '#0a84ff', 'transport'),\n    (new.id, 'Sport',        'expense', '#30d158', 'sport'),\n    (new.id, 'นวด',          'expense', '#bf5af2', 'massage'),\n    (new.id, 'Sport items',  'expense', '#ffd60a', 'ball'),\n    (new.id, 'Petrol cost',  'expense', '#ff453a', 'fuel'),\n    (new.id, 'Housing',      'expense', '#5e5ce6', 'housing'),\n    (new.id, 'Cat',          'expense', '#ac8e68', 'cat'),\n    (new.id, 'Family',       'expense', '#64d2ff', 'family');\n\n  return new;\nend $$;\n\nrevoke execute on function public.handle_new_user() from public, anon, authenticated;"}	remove_budgets_and_reseed_categories	tre.thitipat@gmail.com	\N	\N
20260618165122	{"-- Explicit ordering for categories (your exact sequence, not alphabetical)\nalter table public.categories add column if not exists position int not null default 0;\n\ncreate or replace function public.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  insert into public.wallets (user_id, name, currency, starting_balance)\n  values (new.id, 'Cash', 'USD', 0);\n\n  insert into public.categories (user_id, name, type, color, icon, position) values\n    (new.id, 'Salary',       'income',  '#34c759', 'wallet',    0),\n    (new.id, 'Other income', 'income',  '#30d158', 'plus',      1),\n    (new.id, 'Food',         'expense', '#ff9f0a', 'food',      0),\n    (new.id, 'Expenses',     'expense', '#8e8e93', 'expenses',  1),\n    (new.id, 'Shopping',     'expense', '#ff375f', 'shopping',  2),\n    (new.id, 'Transport',    'expense', '#0a84ff', 'transport', 3),\n    (new.id, 'Sport',        'expense', '#30d158', 'sport',     4),\n    (new.id, 'นวด',          'expense', '#bf5af2', 'massage',   5),\n    (new.id, 'Sport items',  'expense', '#ffd60a', 'ball',      6),\n    (new.id, 'Petrol cost',  'expense', '#ff453a', 'fuel',      7),\n    (new.id, 'Housing',      'expense', '#5e5ce6', 'housing',   8),\n    (new.id, 'Cat',          'expense', '#ac8e68', 'cat',       9),\n    (new.id, 'Family',       'expense', '#64d2ff', 'family',    10);\n\n  return new;\nend $$;\n\nrevoke execute on function public.handle_new_user() from public, anon, authenticated;\n\n-- Apply the same ordering to the existing account\nupdate public.categories set position = case name\n  when 'Salary' then 0\n  when 'Other income' then 1\n  when 'Food' then 0\n  when 'Expenses' then 1\n  when 'Shopping' then 2\n  when 'Transport' then 3\n  when 'Sport' then 4\n  when 'นวด' then 5\n  when 'Sport items' then 6\n  when 'Petrol cost' then 7\n  when 'Housing' then 8\n  when 'Cat' then 9\n  when 'Family' then 10\n  else 99 end\nwhere user_id = '89edc986-7e11-4a99-8556-5185a536ae90';"}	category_position_ordering	tre.thitipat@gmail.com	\N	\N
20260619022333	{"-- Switch to Thai Baht\nupdate public.wallets set currency = 'THB' where user_id = '89edc986-7e11-4a99-8556-5185a536ae90';\n\ncreate or replace function public.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  insert into public.wallets (user_id, name, currency, starting_balance)\n  values (new.id, 'Cash', 'THB', 0);\n\n  insert into public.categories (user_id, name, type, color, icon, position) values\n    (new.id, 'Salary',       'income',  '#34c759', 'wallet',    0),\n    (new.id, 'Other income', 'income',  '#30d158', 'plus',      1),\n    (new.id, 'Food',         'expense', '#ff9f0a', 'food',      0),\n    (new.id, 'Expenses',     'expense', '#8e8e93', 'expenses',  1),\n    (new.id, 'Shopping',     'expense', '#ff375f', 'shopping',  2),\n    (new.id, 'Transport',    'expense', '#0a84ff', 'transport', 3),\n    (new.id, 'Sport',        'expense', '#30d158', 'sport',     4),\n    (new.id, 'นวด',          'expense', '#bf5af2', 'massage',   5),\n    (new.id, 'Sport items',  'expense', '#ffd60a', 'ball',      6),\n    (new.id, 'Petrol cost',  'expense', '#ff453a', 'fuel',      7),\n    (new.id, 'Housing',      'expense', '#5e5ce6', 'housing',   8),\n    (new.id, 'Cat',          'expense', '#ac8e68', 'cat',       9),\n    (new.id, 'Family',       'expense', '#64d2ff', 'family',    10);\n\n  return new;\nend $$;\n\nrevoke execute on function public.handle_new_user() from public, anon, authenticated;"}	currency_thb	tre.thitipat@gmail.com	\N	\N
20260619063833	{"-- TOPgolf: personal golf-practice analytics for Garmin Approach R10 / Garmin Golf CSV exports.\n-- No-auth personal app: the anon role gets full access (data is public to anyone with the URL).\n-- Tables are namespaced golf_* so they never collide with the existing finance tables.\n\ncreate extension if not exists pgcrypto;\n\ncreate table if not exists public.golf_sessions (\n  id              uuid primary key default gen_random_uuid(),\n  played_on       date not null default current_date,\n  title           text,\n  location        text,\n  source_filename text,\n  distance_unit   text not null default 'yds',  -- 'yds' | 'm'\n  speed_unit      text not null default 'mph',  -- 'mph' | 'kph' | 'm/s'\n  notes           text,\n  created_at      timestamptz not null default now()\n);\n\ncreate table if not exists public.golf_shots (\n  id                        uuid primary key default gen_random_uuid(),\n  session_id                uuid not null references public.golf_sessions(id) on delete cascade,\n  shot_index                int,\n  shot_time                 timestamptz,\n  club                      text,\n  club_category             text,   -- Driver | Wood | Hybrid | Iron | Wedge | Putter | Other\n  -- speeds\n  ball_speed                numeric,\n  club_speed                numeric,\n  smash_factor              numeric,\n  -- launch\n  launch_angle              numeric,\n  launch_direction          numeric,\n  -- spin\n  spin_rate                 numeric,\n  spin_axis                 numeric,\n  backspin                  numeric,\n  sidespin                  numeric,\n  -- flight\n  apex_height               numeric,\n  carry_distance            numeric,\n  total_distance            numeric,\n  carry_deviation_angle     numeric,\n  carry_deviation_distance  numeric,  -- + right / - left\n  total_deviation_angle     numeric,\n  total_deviation_distance  numeric,\n  -- club delivery\n  attack_angle              numeric,\n  club_path                 numeric,\n  club_face                 numeric,  -- face angle\n  face_to_path              numeric,\n  -- misc\n  note                      text,\n  raw                       jsonb,    -- original CSV row (header -> value) for export fidelity\n  created_at                timestamptz not null default now()\n);\n\n-- Manual round/score log to track the 105 -> 85 goal (range data alone can't track scores).\ncreate table if not exists public.golf_rounds (\n  id                    uuid primary key default gen_random_uuid(),\n  played_on             date not null default current_date,\n  course                text,\n  score                 int,\n  par                   int default 72,\n  holes                 int default 18,\n  putts                 int,\n  fairways_hit          int,\n  greens_in_regulation  int,\n  notes                 text,\n  created_at            timestamptz not null default now()\n);\n\ncreate index if not exists golf_shots_session_idx  on public.golf_shots(session_id);\ncreate index if not exists golf_shots_club_idx      on public.golf_shots(club);\ncreate index if not exists golf_sessions_played_idx on public.golf_sessions(played_on desc);\ncreate index if not exists golf_rounds_played_idx   on public.golf_rounds(played_on desc);\n\n-- Row Level Security: enabled, with permissive policies for anon (no-login personal app).\nalter table public.golf_sessions enable row level security;\nalter table public.golf_shots    enable row level security;\nalter table public.golf_rounds   enable row level security;\n\ndrop policy if exists golf_sessions_public on public.golf_sessions;\ndrop policy if exists golf_shots_public    on public.golf_shots;\ndrop policy if exists golf_rounds_public   on public.golf_rounds;\n\ncreate policy golf_sessions_public on public.golf_sessions\n  for all to anon, authenticated using (true) with check (true);\ncreate policy golf_shots_public on public.golf_shots\n  for all to anon, authenticated using (true) with check (true);\ncreate policy golf_rounds_public on public.golf_rounds\n  for all to anon, authenticated using (true) with check (true);\n"}	topgolf_schema	tre.thitipat@gmail.com	\N	\N
20260622063824	{"alter table public.categories\n  add column if not exists is_investment boolean not null default false;\n\ncreate or replace function public.handle_new_user()\n returns trigger\n language plpgsql\n security definer\n set search_path to 'public'\nas $function$\nbegin\n  insert into public.wallets (user_id, name, currency, starting_balance)\n  values (new.id, 'Cash', 'THB', 0);\n\n  insert into public.categories (user_id, name, type, color, icon, position, is_investment) values\n    (new.id, 'Salary',          'income',  '#34c759', 'wallet',    0,  false),\n    (new.id, 'Other income',    'income',  '#30d158', 'plus',      1,  false),\n    (new.id, 'Food',            'expense', '#ff9f0a', 'food',      0,  false),\n    (new.id, 'Expenses',        'expense', '#8e8e93', 'expenses',  1,  false),\n    (new.id, 'Shopping',        'expense', '#ff375f', 'shopping',  2,  false),\n    (new.id, 'Transport',       'expense', '#0a84ff', 'transport', 3,  false),\n    (new.id, 'Sport',           'expense', '#30d158', 'sport',     4,  false),\n    (new.id, 'นวด',             'expense', '#bf5af2', 'massage',   5,  false),\n    (new.id, 'Sport items',     'expense', '#ffd60a', 'ball',      6,  false),\n    (new.id, 'Petrol cost',     'expense', '#ff453a', 'fuel',      7,  false),\n    (new.id, 'Housing',         'expense', '#5e5ce6', 'housing',   8,  false),\n    (new.id, 'Cat',             'expense', '#ac8e68', 'cat',       9,  false),\n    (new.id, 'Family',          'expense', '#64d2ff', 'family',    10, false),\n    (new.id, 'หุ้น',            'expense', '#6d5ef0', 'chart',     20, true),\n    (new.id, 'กองทุน',          'expense', '#36a8d8', 'coins',     21, true),\n    (new.id, 'กองทุนลดหย่อน',   'expense', '#30d158', 'shield',    22, true),\n    (new.id, 'คริปโต',          'expense', '#e0a13a', 'crypto',    23, true),\n    (new.id, 'อื่นๆ (ลงทุน)',   'expense', '#98989f', 'tag',       24, true);\n\n  return new;\nend $function$;"}	add_is_investment_to_categories	tre.thitipat@gmail.com	\N	\N
